// odjsonAppend appends the JSON encoding of v to dst.
func (v *Holder) odjsonAppend(dst []byte, m odjsonrt.StringMode) ([]byte, error) {
	var err error
	_ = err
	dst = append(dst, "{\"secret\":"...)
	dst, err = v.Secret.odjsonAppend(dst, m)
	if err != nil {
		return nil, err
	}
	dst = append(dst, ",\"ptr\":"...)
	if v.Ptr == nil {
		dst = append(dst, 'n', 'u', 'l', 'l')
	} else {
		dst, err = (*v.Ptr).odjsonAppend(dst, m)
		if err != nil {
			return nil, err
		}
	}
	dst = append(dst, ",\"list\":"...)
	if v.List == nil {
		dst = odjsonrt.AppendNilSlice(dst, m)
	} else {
		dst = append(dst, '[')
		for i31 := range v.List {
			if i31 > 0 {
				dst = append(dst, ',')
			}
			dst, err = v.List[i31].odjsonAppend(dst, m)
			if err != nil {
				return nil, err
			}
		}
		dst = append(dst, ']')
	}
	dst = append(dst, "}"...)
	return dst, nil
}

// odjsonCapHolderList remembers how long v.List has been, to allocate it once.
